Config._resolveFontEnum = function(arg, arg2)
	local ok, result = pcall(function()
		return Enum.Font[arg]
	end)
	return ok and result or arg2
end
Config._fontProfiles = {
	Merriweather = Config._resolveFontEnum("Merriweather", Enum.Font.GothamBold),
	Builder = Config._resolveFontEnum("BuilderSansBold", Enum.Font.GothamBold),
	Nunito = Config._resolveFontEnum("Nunito", Enum.Font.GothamMedium),
	Ubuntu = Config._resolveFontEnum("Ubuntu", Enum.Font.GothamMedium),
