	Arcade = Config._resolveFontEnum("Arcade", Enum.Font.Code),
	["Sci-Fi"] = Config._resolveFontEnum("SciFi", Enum.Font.Code),
	Code = Config._resolveFontEnum("Code", Enum.Font.Code),
	Bangers = Config._resolveFontEnum("Bangers", Enum.Font.GothamBlack),
}
Config._fontOriginals = setmetatable({}, { __mode = "k" })
Config._fontWatched = setmetatable({}, { __mode = "k" })
Config._fontIsAlternate = function(arg)
	for k, fontProfile in pairs(Config._fontProfiles) do
		if arg == fontProfile then
			return true
		end
	end
	return false
end
Config._fontOriginalFallback = function(arg)
	if arg:IsA("TextLabel") and (tonumber(arg.TextSize) or 0) >= 17 then
		return Enum.Font.GothamBlack
	end
	return Enum.Font.GothamBold
end
Config._refreshHeadDisplayFont = function()
	if not (tbl27.sg and tbl27.sg.Parent) then
		return
	end
	for i, v20 in ipairs(tbl27.brandLabels or {}) do
		if v20 and v20.Parent then
			if Config.fontStyle == "K2 Winter" then
				v20.Font = Enum.Font.GothamBlack
				Config._fontOriginals[v20] = Enum.Font.GothamBlack
			else
				Config._applyFontObject(v20)
			end
		end
	end
	if tbl27.speed and tbl27.speed.Parent then
		if Config.fontStyle == "K2 Winter" then
			tbl27.speed.Font = Enum.Font.GothamBold
			Config._fontOriginals[tbl27.speed] = Enum.Font.GothamBold
		else
			Config._applyFontObject(tbl27.speed)
		end
	end
	if Config._applyVisualTheme then
		pcall(Config._applyVisualTheme)
	end
end
Config._fontRootAllowed = function(arg)
	if not arg then
		return false
	end
	local str = tostring(arg.Name or "")
	arg = str:lower()
	return Config._theme.guiNames[str]
		or arg:find("vx7", 1, true) ~= nil
		or arg:find("miro", 1, true) ~= nil
		or str == "RagCountdownBillboard"
		or str:sub(1, 18) == "EnemyRagCountdown_"
end
Config._fontStyleValid = function(arg)
	for i, v20 in ipairs(Config._fontStyleOrder) do
		if v20 == arg then
			return true
		end
	end
	return false
end
Config._applyFontObject = function(arg)
	if not (arg and (arg:IsA("TextLabel") or (arg:IsA("TextButton")) or (arg:IsA("TextBox")))) then
		return
	end
	local font = Config._fontOriginals[arg]
	if not font or (Config._fontIsAlternate(font)) then
		font = arg.Font
		if Config._fontIsAlternate(font) then
			font = Config._fontOriginalFallback(arg)
		end
		Config._fontOriginals[arg] = font
	end
	local v20 = Config._fontProfiles[Config.fontStyle]
	pcall(function()
		arg.Font = v20 or font
	end)
end
Config._watchFontRoot = function(arg)
	if not Config._fontRootAllowed(arg) or Config._fontWatched[arg] then
		return
	end
	Config._fontWatched[arg] = true
	Config._applyFontObject(arg)
	for i, descendant in ipairs(arg:GetDescendants()) do
		Config._applyFontObject(descendant)
	end
	arg.DescendantAdded:Connect(function(descendant)
		task.defer(Config._applyFontObject, descendant)
		task.delay(0.08, function()
			if descendant and descendant.Parent then
				Config._applyFontObject(descendant)
			end
		end)
	end)
end
Config._applyGlobalFont = function()
	local v20, tbl29 = ipairs, { localPlayer:FindFirstChild("PlayerGui"), CoreGui }
	for k, v21 in v20(tbl29) do
		if v21 then
			for i, child in ipairs(v21:GetChildren()) do
				Config._watchFontRoot(child)
				if Config._fontRootAllowed(child) then
					Config._applyFontObject(child)
					for i2, descendant in ipairs(child:GetDescendants()) do
						Config._applyFontObject(descendant)
					end
				end
			end
		end
	end
end
Config._refreshGlobalFont = function()
	Config._applyGlobalFont()
	task.defer(Config._applyGlobalFont)
	task.delay(0.12, Config._applyGlobalFont)
end
task.defer(function()
	localPlayer:WaitForChild("PlayerGui").ChildAdded:Connect(function(child)
		task.defer(Config._watchFontRoot, child)
	end)
	CoreGui.ChildAdded:Connect(function(child)
		task.defer(Config._watchFontRoot, child)
	end)
	Config._refreshGlobalFont()
end)
