local function fn32(arg)
	if not arg then
		return nil
	end
	local tbl32 = {}
	for k, v23 in pairs(arg) do
		if v23 and v23.type and v23.value then
			local value
			local kind = typeof(v23.value)
			if kind == "string" then
				value = v23.value
			else
				local ok, result = pcall(function()
					return v23.value.Name
				end)
				value = if ok and typeof(result) == "string" then result else value
			end
			if value then
				tbl32[k] = { type = v23.type, value = value }
			end
		end
	end
	return tbl32
end
